sha 42317434ba2b321f7c2487f453669db4fcb8be5f96f855af7bd290fc4db21aab lines 489 baseline 4711: /** Platform-neutral serial coordination. No command execution, network or persistence.
2:  * Registry and host attestations are trusted inputs, never imported from Task Context.
3:  */
4: import { createHash, randomUUID } from 'node:crypto';
5: import { lstatSync, readFileSync, readdirSync, realpathSync } from 'node:fs';
6: import path from 'node:path';
7: 
8: export const digest = value => createHash('sha256').update(JSON.stringify(value)).digest('hex');
9: export const operationBinding = host => digest(host.requests ?? {});
10: export const taskBinding = task => digest({ id: task.id, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions });
11: const copy = value => JSON.parse(JSON.stringify(value));
12: const assert = (ok, message) => { if (!ok) throw new Error(message); };
13: const recovered = new WeakMap();
14: const runtimeTasks = new WeakSet();
15: const runtimeExecutions = new WeakMap();
16: const states = new Set(['pending', 'running', 'completed', 'reused', 'skipped', 'evidence_insufficient', 'permission_blocked', 'validation_failed', 'interrupted']);
17: const allowedCapabilities = ['read_files', 'write_files', 'run_shell_commands', 'access_network', 'destructive_actions_allowed'];
18: const safePath = p => typeof p === 'string' && p !== '' && !path.isAbsolute(p) && !p.split(/[\\/]/).includes('..');
19: 
20: function checkPath(root, relative) {
21:   assert(safePath(relative), 'Dependency path must be repository-relative');
22:   let current = realpathSync(root);
23:   for (const part of relative.split(/[\\/]/)) {
24:     current = path.join(current, part);
25:     try { assert(!lstatSync(current).isSymbolicLink(), 'Symlink paths require host inspection'); }
26:     catch (error) { if (error.code !== 'ENOENT') throw error; }
27:   }
28:   return current;
29: }
