31: // Include directory membership (new/deleted files), executable bits and file bytes.
32: // Never follow symlinks or read outside the explicitly supplied repository root.
33: export function fingerprint(root, relative) {
34:   const current = checkPath(root, relative);
35:   try { lstatSync(current); } catch (error) { if (error.code === 'ENOENT') return 'missing'; throw error; }
36:   function visit(file) {
37:     const stat = lstatSync(file);
38:     assert(!stat.isSymbolicLink(), 'Symlink dependencies require host inspection');
39:     if (stat.isDirectory()) return readdirSync(file).sort().map(name => [name, visit(path.join(file, name))]);
40:     assert(stat.isFile(), 'Only regular files/directories can be fingerprinted');
41:     return [stat.mode & 0o111, createHash('sha256').update(readFileSync(file)).digest('hex')];
42:   }
43:   return digest(visit(current));
44: }
