46: export function captureEvidence(root, input, environment) {
47:   assert(input.id && input.source && input.summary, 'Evidence needs id, source and summary');
48:   assert(Array.isArray(input.dependencies) && input.dependencies.length, 'Evidence needs dependency coverage');
49:   const bindings = Object.fromEntries(input.dependencies.map(p => [p, fingerprint(root, p)]));
50:   return { ...copy(input), bindings, environment: copy(environment), recorded_at: new Date().toISOString() };
51: }
