53: export function evidenceValidity(evidence, host) {
54:   if (!evidence || !host.trustedEvidence?.has(digest(evidence))) return { status: 'unknown', reason: 'source_not_attested' };
55:   if (!['pass', 'fail'].includes(evidence.result)) return { status: 'unknown', reason: 'result_not_observed' };
56:   let unknownReason = evidence.coverage_complete !== true || !evidence.bindings || !Object.keys(evidence.bindings).length
57:     || !evidence.environment || !Object.keys(evidence.environment).length
58:     ? 'dependency_or_environment_coverage_unknown' : null;
59:   if (evidence.kind === 'test' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code) || (evidence.result === 'pass' ? evidence.exit_code !== 0 : evidence.exit_code === 0))) {
60:     unknownReason ??= 'execution_receipt_missing';
61:   }
62:   if (evidence.kind === 'signal' && (!evidence.command || !evidence.cwd || !Number.isInteger(evidence.exit_code)
63:       || evidence.observed_target_failure !== true || !evidence.success_criterion || !evidence.failure_criterion)) {
64:     unknownReason ??= 'reliable_failure_signal_missing';
65:   }
66:   for (const [key, value] of Object.entries(evidence.environment ?? {})) {
67:     if (!(key in (host.environment ?? {}))) { unknownReason ??= `environment_unknown:${key}`; continue; }
68:     if (host.environment[key] !== value) return { status: 'stale', reason: `environment_changed:${key}` };
69:   }
70:   for (const [file, hash] of Object.entries(evidence.bindings ?? {})) {
71:     try {
72:       if (fingerprint(host.root, file) !== hash) return { status: 'stale', reason: `dependency_changed:${file}` };
73:     } catch (error) { unknownReason ??= error.message; }
74:   }
75:   if (unknownReason) return { status: 'unknown', reason: unknownReason };
76:   return evidence.result === 'pass' ? { status: 'valid', reason: 'attested_inputs_unchanged' } : { status: 'failed', reason: 'observed_failure' };
77: }
