79: export function validationPlan(evidence, host) {
80:   return evidence.map(item => ({ id: item.id, ...evidenceValidity(item, host) }))
81:     .map(item => ({ ...item, action: item.status === 'valid' ? 'reuse' : item.status === 'unknown' ? 'investigate' : 'rerun' }));
82: }
