84: export function reviewBinding(root, task, baseline, files) {
85:   assert(baseline && Array.isArray(files) && files.length, 'Review needs a baseline and complete changed/related paths');
86:   return digest({ baseline, goal: task.goal, acceptance: task.acceptance, decisions: task.decisions,
87:     files: [...new Set(files)].sort().map(file => [file, fingerprint(root, file)]) });
88: }
