90: function definition(task, registry, inventory) {
91:   assert(runtimeTasks.has(task), 'Untrusted Task Context: use createTask or restoreTask');
92:   assert(task.registry_binding === digest(registry), 'Registry changed; explicitly migrate/reselect workflow');
93:   if (task.workflow_id) {
94:     const workflow = registry.workflows[task.workflow_id];
95:     assert(workflow, 'Unknown registered workflow');
96:     return workflow;
97:   }
98:   assert(inventory.has(task.skill_id), 'Unknown single Skill');
99:   return { stages: [{ id: 'task', type: 'skill', skill: task.skill_id, optional: false, condition: 'always', prerequisites: [], next: [], permission: 'request_scoped', stop_conditions: [] }], stop_conditions: [] };
100: }
