102: export function createTask({ id, goal, acceptance, workflow_id = null, skill_id = null }, registry, inventory) {
103:   assert(id && goal && Array.isArray(acceptance) && acceptance.length, 'Goal and acceptance are required');
104:   assert(acceptance.every(item => typeof item === 'string' && item.length) && new Set(acceptance).size === acceptance.length, 'Acceptance IDs must be distinct strings');
105:   assert(Boolean(workflow_id) !== Boolean(skill_id), 'Choose one registered workflow or one existing Skill');
106:   const task = { schema_version: 2, id, goal, acceptance: copy(acceptance), workflow_id, skill_id,
107:     registry_binding: digest(registry), decisions: [], scope: { files: [], modules: [], interfaces: [] },
108:     risks: [], permission_refs: [], evidence: [], changes: [], unresolved: [], next_actions: [],
109:     current_stage: null, steps: {}, history: [] };
110:   runtimeTasks.add(task);
111:   for (const stage of definition(task, registry, inventory).stages) task.steps[stage.id] = { status: 'pending', attempts: 0, evidence_ids: [] };
112:   return task;
113: }
