115: function evidenceFor(task, ids, host) {
116:   return ids?.length > 0 && ids.every(id => {
117:     const evidence = task.evidence.find(e => e.id === id);
118:     return evidence?.task_binding === taskBinding(task) && evidenceValidity(evidence, host).status === 'valid';
119:   });
120: }
121: function condition(task, name, host) {
122:   if (name === 'always') return true;
123:   const fact = host.conditions?.[name];
124:   return fact && typeof fact.value === 'boolean' && fact.reason && evidenceFor(task, fact.evidence_ids, host) ? fact.value : undefined;
125: }
126: function permission(skill, stage, task, host) {
127:   const metadata = host.inventory.get(skill);
128:   if (!metadata || !['draft', 'beta', 'stable'].includes(metadata.status)) return 'skill_unavailable';
129:   const request = host.requests?.[stage.id];
130:   if (!request) return 'operation_scope_missing';
131:   if (!Array.isArray(request.capabilities) || !request.capabilities.length) return 'capabilities_missing';
132:   if (stage.permission === 'write_scoped' && !request.capabilities.includes('write_files')) return 'write_scope_missing';
133:   if (stage.permission === 'read_only' && request.capabilities.includes('write_files')) return 'read_only_stage';
134:   for (const capability of request.capabilities) {
135:     if (!allowedCapabilities.includes(capability) || metadata.permissions?.[capability] !== true
136:         || host.capabilities?.[capability] !== true) return `capability_denied:${capability}`;
137:     const grants = host.grants?.filter(g => g.task_id === task.id && g.capability === capability && g.source
138:       && g.skills.includes(skill)) ?? [];
139:     if (!grants.length) return `user_authorization_missing:${capability}`;
140:     if (['read_files', 'write_files'].includes(capability)) {
141:       if (!request.paths?.length || request.paths.some(p => !safePath(p))) return 'explicit_paths_missing';
142:       if (request.paths.some(p => !grants.some(g => g.paths?.includes(p)))) return `path_not_authorized:${capability}`;
143:       try { for (const p of request.paths) checkPath(host.root, p); } catch { return 'unsafe_path'; }
144:     } else if (!request.operation || !grants.some(g => g.operations?.includes(request.operation))) return `operation_not_authorized:${capability}`;
145:   }
146:   const check = host.skillChecks?.[stage.id];
147:   if (!check?.source || check.request_binding !== digest(request) || check.skill_binding !== digest(metadata) || check.allowed !== true) return 'skill_scope_not_verified';
148:   if (request.capabilities.includes('run_shell_commands') && request.preflight !== 'safe') return 'command_preflight_missing';
149:   return null;
150: }
151: 
152: function potentiallyEffectful(stage, host) {
153:   return host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files') || stage.permission === 'write_scoped';
154: }
155: 
156: function writes(stage, host) {
157:   return stage.permission === 'write_scoped' || (stage.permission === 'request_scoped' && host.requests?.[stage.id]?.capabilities?.includes('write_files'));
158: }
