164: export function recoveryBinding(task, host) {
165:   const checkpoint = recovered.get(task);
166:   return checkpoint ? digest({ checkpoint, intent: taskBinding(task), requests: host.requests, skillChecks: host.skillChecks }) : null;
167: }
