169: export function recoveredExecutionBinding(task, stageId, host) {
170:   return digest({ recovery: recoveryBinding(task, host), stage: stageId, attempts: task.steps[stageId]?.attempts, execution_nonce: task.steps[stageId]?.execution_nonce, request: host.requests?.[stageId] });
171: }
