173: function requirement(task, requirement, host) {
174:   return task.evidence.some(e => e.claims?.includes(requirement.claim)
175:     && e.task_binding === taskBinding(task) && e.operation_binding === operationBinding(host)
176:     && (!requirement.skill || e.skill === requirement.skill)
177:     && (!requirement.kind || e.kind === requirement.kind)
178:     && (requirement.kind !== 'review' || (e.kind === 'review' && e.independent === true && host.reviewBinding && e.review_basis === host.reviewBinding))
179:     && evidenceValidity(e, host).status === 'valid');
180: }
