182: function stepEvidence(task, stage, host, executionOwner = task) {
183:   const step = task.steps[stage.id];
184:   if (!evidenceFor(task, step.evidence_ids, host)) return false;
185:   const explicitReuse = step.status === 'reused'
186:     && Array.isArray(host.reuse?.[stage.id]) && digest(host.reuse[stage.id]) === digest(step.evidence_ids);
187:   if (step.status === 'reused' && !explicitReuse) return false;
188:   const evidence = step.evidence_ids.map(id => task.evidence.find(e => e.id === id));
189:   const scoped = evidence.filter(e => e.skill === stage.skill && e.request_binding === digest(host.requests[stage.id]) && e.claims?.includes(`stage:${stage.id}`)
190:     && (explicitReuse || (runtimeExecutions.get(executionOwner)?.get(stage.id) === step.execution_nonce
191:       && typeof step.execution_nonce === 'string' && e.execution_attempt === step.attempts
192:       && e.execution_nonce === step.execution_nonce)));
193:   if (!scoped.length) return false;
194:   if (stage.skill === 'safe-code-review' && !scoped.some(e => e.kind === 'review' && e.independent === true
195:       && e.review_basis && e.review_basis === host.reviewBinding)) return false;
196:   if (stage.skill === 'bug-root-cause-analysis' && !scoped.some(e => e.signal_ids?.length
197:       && e.signal_ids.every(id => task.evidence.some(signal => signal.id === id && signal.kind === 'signal' && signal.task_binding === taskBinding(task)
198:         && evidenceValidity(signal, host).status === 'valid')))) return false;
199:   return true;
200: }
201: 
202: function unresolvedFailures(task, host) {
203:   const unresolved = [];
204:   for (const failed of task.evidence.filter(e => e.kind === 'test' && e.result === 'fail')) {
205:     const validity = evidenceValidity(failed, host);
206:     if (validity.status === 'stale' || validity.reason === 'source_not_attested') continue;
207:     if (validity.status === 'unknown') {
208:       unresolved.push(failed);
209:       continue;
210:     }
211:     const resolution = host.failureResolutions?.get(digest(failed));
212:     const replacement = resolution?.source && task.evidence.find(e => e.id === resolution.replacement);
213:     const identity = e => digest({ command: e.command, cwd: e.cwd, bindings: e.bindings, environment: e.environment });
214:     if (!replacement || replacement.task_binding !== taskBinding(task) || replacement.kind !== 'test'
215:         || evidenceValidity(replacement, host).status !== 'valid' || identity(replacement) !== identity(failed)
216:         || !(Date.parse(replacement.recorded_at) > Date.parse(failed.recorded_at))) {
217:       unresolved.push(failed);
218:     }
219:   }
220:   return unresolved;
221: }
