223: /** Recompute a decision every time. No imported context field grants execution authority. */
224: export function nextAction(task, host) {
225:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
226:   const workflow = definition(task, host.registry, host.inventory);
227:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
228:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
229:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
230:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
231:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
232:   const recovery = recoveryBinding(task, host);
233:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
234:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
235:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
236:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
237:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
238:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
239:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
240:   const completed = new Set();
241:   for (const stage of workflow.stages) {
242:     const step = task.steps[stage.id];
243:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
244:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
245:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
246:     }
247:     const applies = condition(task, stage.condition, host);
248:     const decision = { stage: stage.id, skill: stage.skill };
249:     const stopAssessments = [...new Set([...(workflow.stop_conditions ?? []), ...stage.stop_conditions])].map(name => [name, condition(task, name, host)]);
250:     const stop = stopAssessments.find(([, value]) => value === true);
251:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop[0]}` };
252:     const unknownStop = stopAssessments.find(([, value]) => value === undefined);
253:     if (unknownStop) return { ...decision, action: 'evidence_insufficient', reason: `stop_condition_unknown:${unknownStop[0]}` };
254:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
255:     // Completed effects stay protected even when applicability changes. A new receipt
256:     // is not a reconciliation of the previous attempt's potentially different effects.
257:     const wasCompleted = ['completed', 'reused'].includes(step.status);
258:     const effectful = step.effect_state === 'known' || writes(stage, host)
259:       || host.requests?.[stage.id]?.capabilities?.some(c => c !== 'read_files');
260:     if (stage.type === 'skill' && wasCompleted) {
261:       const denied = permission(stage.skill, stage, task, host);
262:       if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
263:       if (!stepEvidence(task, stage, host)) {
264:         if (effectful && !evidenceFor(task, step.evidence_ids, host)) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
265:         const reusable = host.reuse?.[stage.id];
266:         if (reusable) {
267:           const provisional = copy(task);
268:           provisional.steps[stage.id].status = 'reused';
269:           provisional.steps[stage.id].evidence_ids = reusable;
270:           if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: reusable, reason: 'explicit_recovered_or_historical_result_reuse' };
271:         }
272:         if (effectful) return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
273:       }
274:     }
275:     if (!applies) {
276:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
277:       // Applicability must not erase a completed operation or its known effects.
278:       if (['completed', 'reused'].includes(step.status)) {
279:         if (stage.type === 'skill' && !stepEvidence(task, stage, host)) return { ...decision, action: 'evidence_insufficient', reason: 'historical_stage_requires_explicit_reuse' };
280:         completed.add(stage.id); continue;
281:       }
282:       if (recovery && stage.type === 'skill') {
283:         const reusable = host.reuse?.[stage.id];
284:         if (reusable) {
285:           const provisional = copy(task);
286:           provisional.steps[stage.id].status = 'reused';
287:           provisional.steps[stage.id].evidence_ids = reusable;
288:           const denied = permission(stage.skill, stage, task, host);
289:           if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
290:           if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: reusable, reason: 'observed_effect_before_checkpoint_recovery' };
291:         }
292:         const disposition = host.recoveredExecutionChecks?.get(recoveredExecutionBinding(task, stage.id, host));
293:         if (!disposition?.source || disposition.disposition !== 'not_executed') {
294:           return { ...decision, action: 'blocked', reason: 'recovered_skipped_effect_needs_disposition' };
295:         }
296:       }
297:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };
298:       completed.add(stage.id); continue;
299:     }
300:     if (stage.type === 'gate') {

300:     if (stage.type === 'gate') {
301:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
302:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
303:       for (const child of children) {
304:         const denied = permission(child.skill, child, task, host);
305:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
306:       }
307:       // Always re-evaluate gates against host grants, never reuse persisted approval.
308:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
309:       completed.add(stage.id); continue;
310:     }
311:     const denied = permission(stage.skill, stage, task, host);
312:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
313:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
314:       completed.add(stage.id); continue;
315:     }
316:     const failure = step.status === 'validation_failed';
317:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
318:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
319:     if (potentiallyEffectful(stage, host)) {
320:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
321:         .find(r => !requirement(task, r, host));
322:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
323:     }
324:     const candidate = host.reuse?.[stage.id];
325:     if (candidate) {
326:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate; provisional.steps[stage.id].status = 'reused';
327:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
328:     }
329:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
330:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
331:     }
332:     if (host.verificationDeferral?.active === true) {
333:       const request = host.requests[stage.id];
334:       if (!host.verificationDeferral.source) {
335:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferral_source_missing' };
336:       }
337:       if (request.capabilities.includes('run_shell_commands') && typeof request.verification !== 'boolean') {
338:         return { ...decision, action: 'evidence_insufficient', reason: 'command_verification_purpose_unknown' };
339:       }
340:       if (request.verification === true) {
341:         return { ...decision, action: 'evidence_insufficient', reason: 'verification_deferred',
342:           verification_status: 'verification_deferred', source: host.verificationDeferral.source,
343:           pending: host.verificationDeferral.pending ?? [], release_authorized: false };
344:       }
345:     }
346:     if (recovery && stage.type === 'skill') {
347:       const disposition = host.recoveredExecutionChecks?.get(recoveredExecutionBinding(task, stage.id, host));
348:       if (!disposition?.source || !['not_executed', 'safe_retry'].includes(disposition.disposition)
349:           || (disposition.disposition === 'safe_retry' && !host.reconciled?.has(reconciliationBinding(task, stage.id, host)))) {
350:         return { ...decision, action: 'blocked', reason: 'recovered_execution_needs_explicit_disposition' };
351:       }
352:     }
353:     const unresolved = unresolvedFailures(task, host).find(failed => {
354:       const repair = host.failureRepairs?.get(digest(failed));
355:       return !repair?.source || repair.stages?.[stage.id] !== digest(host.requests[stage.id]);
356:     });
357:     if (unresolved) return { ...decision, action: evidenceValidity(unresolved, host).status === 'unknown' ? 'evidence_insufficient' : 'validation_failed', reason: 'unresolved_current_test_failure', evidence_id: unresolved.id };
358:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
359:   }
