411:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
412:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
413:     event(task, action.stage, step.status, action.reason);
